import{_ as s,C as r,o as n,c as i,a2 as a,j as t,a as d,E as l}from"./chunks/framework.CHjbm2Wd.js";const k=JSON.parse('{"title":"Lunar FSW Field Guide","description":"A 16-week path from software developer to lunar lander GNC and flight software.","frontmatter":{"layout":"home","title":"Lunar FSW Field Guide","description":"A 16-week path from software developer to lunar lander GNC and flight software.","hero":{"name":"Lunar FSW","text":"Field Guide","tagline":"A 16-week path from software developer to lunar lander GNC and flight software. Deep dives, buildable exercises, and the flight-software topics the original plan left out.","image":{"src":"/hero.svg","alt":"A lunar lander on a powered descent trajectory above the Moon"},"actions":[{"theme":"brand","text":"Start the roadmap","link":"/start/roadmap"},{"theme":"alt","text":"How to use this guide","link":"/start/how-to-use"}]},"features":[{"icon":"◐","title":"Frames, quaternions, 6DOF","details":"Build the math spine first. Learn to keep frames, units, signs, and time tags straight before they cost you a week."},{"icon":"⌖","title":"Navigation & guidance","details":"EKF, sensor fusion, error propagation, powered descent phases, throttle, attitude, and abort logic."},{"icon":"Δ","title":"Flight software","details":"Real-time C++, Simulink code generation, cFS, RTOS scheduling, CCSDS, and fault protection."},{"icon":"✓","title":"V&V and test","details":"Requirements traceability, SIL/HIL, Python automation, Monte Carlo, and the evidence a reviewer actually asks for."},{"icon":"◎","title":"Mission context","details":"Lunar gravity, vacuum, dust, lighting, plume-surface interaction, and one-shot landing constraints."},{"icon":"⌁","title":"Project bridge","details":"Every module maps back to the LLV PDI console you are already building. Study becomes working code."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1792993690000}'),h={name:"index.md"},c={class:"home-section"};function p(u,e,m,g,f,b){const o=r("ProgressDashboard");return n(),i("div",null,[e[2]||(e[2]=a('<div class="home-section"><p class="home-kicker">The plan, repaired</p><h2 id="what-this-site-is" tabindex="-1">What this site is <a class="header-anchor" href="#what-this-site-is" aria-label="Permalink to &quot;What this site is&quot;">​</a></h2><p>This is a working field guide, not a link dump. It follows the three-month plan in <code>GNC.md</code>, fixes its ordering, and adds the Month 4 flight-software track that the skills table implied but the schedule never covered.</p><p>The goal is narrow: <strong>turn you into someone who can take a GNC algorithm, integrate it into a flight-software architecture, test it, and defend the evidence.</strong> That is the job described by the lunar-lander roles you are targeting.</p></div><div class="home-section"><p class="home-kicker">Start here</p><h2 id="three-ways-in" tabindex="-1">Three ways in <a class="header-anchor" href="#three-ways-in" aria-label="Permalink to &quot;Three ways in&quot;">​</a></h2><div class="home-grid"><a class="home-card" href="./start/roadmap.html"><span class="card-index">01</span><strong>Follow the 16-week roadmap</strong><span>Week-by-week sequence, deliverables, and the capstone that ties everything together.</span></a><a class="home-card" href="./start/how-to-use.html"><span class="card-index">02</span><strong>Learn how to study this</strong><span>The read → build → explain → test loop, plus what to skip when time is short.</span></a><a class="home-card" href="./start/progress.html"><span class="card-index">03</span><strong>Open the progress dashboard</strong><span>Mark pages complete, see the next topic, and keep the whole plan in view.</span></a></div></div><div class="home-section"><p class="home-kicker">The route</p><h2 id="four-months-one-trajectory" tabindex="-1">Four months, one trajectory <a class="header-anchor" href="#four-months-one-trajectory" aria-label="Permalink to &quot;Four months, one trajectory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Focus</th><th>What you can do at the end</th></tr></thead><tbody><tr><td><strong>Month 1</strong></td><td>Space basics, frames primer, STK, MATLAB/Simulink, C++, Linux, Git, CMake, debugging</td><td>Build and debug a small lander simulation. Navigate a lunar scenario in STK.</td></tr><tr><td><strong>Month 2</strong></td><td>Frames, quaternions, attitude dynamics, PID/LQR, 6DOF, Monte Carlo, navigation, powered descent, architecture</td><td>Close the loop: estimate state, generate a descent command, control attitude, and analyze dispersions.</td></tr><tr><td><strong>Month 3</strong></td><td>V&amp;V, SIL/HIL, Python automation, STK Object Model</td><td>Produce test evidence, automate a test campaign, and script repeatable mission studies.</td></tr><tr><td><strong>Month 4</strong></td><td>Real-time C++, Simulink pipeline, cFS, RTOS, CCSDS/SpaceWire, NPR 7150.2, fault protection, sensors</td><td>Speak credibly about the flight-software stack and build a small cFS or RTOS-based lander app.</td></tr></tbody></table></div>',3)),t("div",c,[e[0]||(e[0]=t("p",{class:"home-kicker"},"Keep moving",-1)),e[1]||(e[1]=t("h2",{id:"your-progress",tabindex:"-1"},[d("Your progress "),t("a",{class:"header-anchor",href:"#your-progress","aria-label":'Permalink to "Your progress"'},"​")],-1)),l(o,{compact:""})]),e[3]||(e[3]=a('<div class="home-section"><p class="home-kicker">Read this first</p><h2 id="the-honest-constraints" tabindex="-1">The honest constraints <a class="header-anchor" href="#the-honest-constraints" aria-label="Permalink to &quot;The honest constraints&quot;">​</a></h2><ul><li><strong>The original plan is broad, not deep.</strong> One month cannot make you an expert in eight tools. This guide compresses the tooling and spends the saved time on GNC and flight software.</li><li><strong>STK is much easier after frames and time.</strong> The roadmap inserts a short frames primer before STK instead of pretending the order does not matter.</li><li><strong>“Orbital mechanics is lower priority” is only half true.</strong> You do not need the full three-body problem, but you do need two-body motion, frames, time, and descent mechanics. The mission pages scope that sharply.</li><li><strong>V&amp;V is not a Month 3 phase.</strong> It starts when you write the first requirement. The Month 3 pages turn the habit into evidence.</li><li><strong>cFS, RTOS, CCSDS, and NPR 7150.2 were missing.</strong> They are now Month 4, because they are exactly what lunar-lander flight-software interviews probe.</li></ul><blockquote><p>If you only have ten hours a week, stretch the calendar. Do not compress Month 2. A weak navigation or guidance foundation shows up immediately in an interview and in the simulator.</p></blockquote></div>',1))])}const y=s(h,[["render",p]]);export{k as __pageData,y as default};
